-- Relay migration 013: workflow state machine columns
-- (ticket baebf8b7; design doc ch. 15): workflows gain states and
-- transitions JSONB (the full state machine of a workflow), and
-- tickets gain workflow_id (the workflow the ticket follows; NULL
-- means the built-in 14-state development flow). The default
-- workflow's states/transitions are filled from the built-in
-- definition below: the JSON was generated by node from
-- server/stateMachine.js (BUILTIN_STATES / BUILTIN_DEFINITION),
-- not hand-copied, so the seed and the built-in fallback are
-- identical. Existing tickets keep workflow_id NULL and follow the
-- built-in flow, exactly as before.
-- Idempotent: safe to run on every server startup.

ALTER TABLE workflows
  ADD COLUMN IF NOT EXISTS states JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS transitions JSONB NOT NULL DEFAULT '[]'::jsonb;

ALTER TABLE tickets
  ADD COLUMN IF NOT EXISTS workflow_id UUID REFERENCES workflows(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_tickets_workflow ON tickets (workflow_id);

-- The seed UPDATE is guarded on the is_default column existing:
-- migration 020 drops is_default, and the server re-runs every
-- migration on startup, so an unguarded UPDATE would fail on the
-- second run (column does not exist).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'workflows' AND column_name = 'is_default') THEN
    UPDATE workflows
      SET states = '[{"code":"requirement","label":"Requirement","sort_order":0,"is_start":true,"is_terminal":false},{"code":"decomposing","label":"Decomposing","sort_order":1,"is_start":false,"is_terminal":false},{"code":"needs_clarification","label":"Needs clarification","sort_order":2,"is_start":false,"is_terminal":false},{"code":"pending_dev","label":"Pending dev","sort_order":3,"is_start":false,"is_terminal":false},{"code":"in_dev","label":"In dev","sort_order":4,"is_start":false,"is_terminal":false},{"code":"pending_review","label":"Pending review","sort_order":5,"is_start":false,"is_terminal":false},{"code":"in_review","label":"In review","sort_order":6,"is_start":false,"is_terminal":false},{"code":"pending_test","label":"Pending test","sort_order":7,"is_start":false,"is_terminal":false},{"code":"in_test","label":"In test","sort_order":8,"is_start":false,"is_terminal":false},{"code":"needs_acceptance_clarification","label":"Needs acceptance clarification","sort_order":9,"is_start":false,"is_terminal":false},{"code":"pending_deploy","label":"Pending deploy","sort_order":10,"is_start":false,"is_terminal":false},{"code":"deploying","label":"Deploying","sort_order":11,"is_start":false,"is_terminal":false},{"code":"delivered","label":"Delivered","sort_order":12,"is_start":false,"is_terminal":true},{"code":"cancelled","label":"Cancelled","sort_order":13,"is_start":false,"is_terminal":true}]'::jsonb, transitions = '[{"from":"needs_clarification","to":"decomposing","role":"pm","requiresReason":true,"requiresHandoff":false,"selfCheck":false,"kind":"clarify"},{"from":"requirement","to":"decomposing","role":"leader","requiresReason":false,"requiresHandoff":false,"selfCheck":false,"kind":"forward"},{"from":"decomposing","to":"needs_clarification","role":"leader","requiresReason":true,"requiresHandoff":false,"selfCheck":false,"kind":"clarify"},{"from":"decomposing","to":"pending_dev","role":"leader","requiresReason":false,"requiresHandoff":true,"selfCheck":false,"kind":"forward"},{"from":"pending_dev","to":"in_dev","role":"engineer","requiresReason":false,"requiresHandoff":false,"selfCheck":false,"kind":"pickup"},{"from":"in_dev","to":"pending_review","role":"engineer","requiresReason":false,"requiresHandoff":true,"selfCheck":false,"kind":"forward"},{"from":"in_dev","to":"needs_clarification","role":"engineer","requiresReason":true,"requiresHandoff":false,"selfCheck":false,"kind":"clarify"},{"from":"pending_review","to":"in_review","role":"reviewer","requiresReason":false,"requiresHandoff":false,"selfCheck":true,"kind":"pickup"},{"from":"in_review","to":"pending_test","role":"reviewer","requiresReason":false,"requiresHandoff":false,"selfCheck":true,"kind":"forward"},{"from":"in_review","to":"in_dev","role":"reviewer","requiresReason":true,"requiresHandoff":false,"selfCheck":true,"kind":"return"},{"from":"pending_test","to":"in_test","role":"tester","requiresReason":false,"requiresHandoff":false,"selfCheck":true,"kind":"pickup"},{"from":"in_test","to":"pending_deploy","role":"tester","requiresReason":false,"requiresHandoff":false,"selfCheck":true,"kind":"forward"},{"from":"in_test","to":"in_dev","role":"tester","requiresReason":true,"requiresHandoff":false,"selfCheck":true,"kind":"return"},{"from":"in_test","to":"needs_acceptance_clarification","role":"tester","requiresReason":true,"requiresHandoff":false,"selfCheck":true,"kind":"clarify"},{"from":"needs_acceptance_clarification","to":"in_test","role":"pm","requiresReason":true,"requiresHandoff":false,"selfCheck":false,"kind":"clarify"},{"from":"pending_deploy","to":"deploying","role":"deployer","requiresReason":false,"requiresHandoff":false,"selfCheck":true,"kind":"pickup"},{"from":"deploying","to":"delivered","role":"deployer","requiresReason":false,"requiresHandoff":false,"selfCheck":true,"kind":"forward"},{"from":"deploying","to":"in_test","role":"deployer","requiresReason":true,"requiresHandoff":false,"selfCheck":true,"kind":"return"}]'::jsonb
      WHERE is_default AND states = '[]'::jsonb;
  END IF;
END $$;
